$ErrorActionPreference='Stop'; if (@(Get-ExecutionPolicy -List | Where-Object {$_.ExecutionPolicy -in @('AllSigned','Restricted')}).Count) {throw 'IT signing policy restricts this installer'}; [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; $jjDir=Join-Path $env:TEMP ('jjaitech-install-'+[guid]::NewGuid().ToString('N')); New-Item -ItemType Directory -Path $jjDir | Out-Null; $jjZip=Join-Path $jjDir 'release.zip'; Invoke-WebRequest -UseBasicParsing -Uri 'https://github.com/JachinLan/jjaitech-memory/releases/download/v1.4.0-rc.1-online.1/jjaitech-memory-windows-1.4.0-rc.1-online.1.zip' -OutFile $jjZip -TimeoutSec 120; if ((Get-FileHash -Algorithm SHA256 -LiteralPath $jjZip).Hash.ToLowerInvariant() -ne '2fb2d77293e3dd4b0c6df3adee2a94ae33f265b4da67cf79ed31fe13dfc57160') {throw 'Download checksum mismatch; installation stopped'}; Expand-Archive -LiteralPath $jjZip -DestinationPath $jjDir; & ([scriptblock]::Create([IO.File]::ReadAllText((Join-Path $jjDir 'jjaitech-memory/distribution/bootstrap-windows.ps1')))) -PackageRoot $jjDir
